465	// ReviewResumeDelay computes a bounded, non-polling wait; callers revalidate afterwards.
466	func ReviewResumeDelay(r ReviewRun, now time.Time, max time.Duration, jitter time.Duration) (time.Duration, error) {
467		if r.Interruption == nil || r.Interruption.ResetAt == "" {
468			return 0, fmt.Errorf("no recorded reset instant")
469		}
470		if max <= 0 || max > 24*time.Hour || jitter < 0 || jitter > time.Second {
471			return 0, fmt.Errorf("wait bound must be positive and at most 24h; jitter at most 1s")
472		}
473		reset, e := time.Parse(time.RFC3339Nano, r.Interruption.ResetAt)
474		if e != nil {
475			return 0, e
476		}
477		delay := reset.Sub(now)
478		if delay < 0 {
479			delay = 0
480		}
481		delay += jitter
482		if delay > max {
483			return 0, fmt.Errorf("recorded reset exceeds maximum wait")
484		}
485		return delay, nil
486	}
